    source('src-paradise-towers-reference', 'Paradise Towers', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/Paradise_Towers', 'secondary_tv_plot_reference_indexed', 'Public remaining residents, caretakers, cannibalism and killing-cleaner passages read', 'Automated building services are repurposed to kill residents.', 'A damaged residential facility and empty utopian sales language do not establish a durable automatic support economy.'),
