    decision('c0402', 'needs_evidence', 'Ten-C energy capabilities do not establish a supported population’s economic institutions.', ['src-ten-c-reference'], analysis='The nonhumanoid species needs an explicit person proxy and actual distribution mechanism before scoring.', follow_up='Skip deeper lore reconstruction.'),
    decision('c0403', 'needs_evidence', 'Post-Burn fragmentation does not resolve ordinary household access for a scoped Federation population.', ['src-post-burn-federation-reference'], analysis='The TNG provision estimate cannot simply be copied across a major infrastructure and political break.', follow_up='Skip reconstructing multiple seasons to rescue this aggregate.'),
    decision('c0404', 'needs_evidence', 'Solum’s contact and civil-war history does not establish post-work production and allocation.', ['src-solum-reference'], analysis='Technological sophistication and alternate futures are not a stable material constitution.', follow_up='Skip deeper timeline reconstruction.'),
    decision('c0405', 'included', 'Primary dialogue directly connects free material needs to synthesizers and separates survival from employment.', u, society_id='orville-union-synthesizer-economy'),
    decision('c0406', 'boundary_case', 'The Kaylon machine civilization is not a verified supported human or human-derived post-work community.', ['src-kaylon-builders-reference'], analysis='Active artificial persons still perform useful functions; extinct Builders are not their leisure population.', follow_up='Keep as an autonomous-machine personhood comparison.'),
    decision('c0407', 'needs_evidence', 'Builder household servants do not establish the biological civilization’s wider material distribution.', ['src-kaylon-builders-reference', 'src-kaylon-household-reference'], analysis='Slavery and a purchased domestic robot demonstrate replacement of tasks, without enough evidence of continuing work-independent necessities for a defined cohort.', follow_up='Skip detailed flashback reconstruction.'),
    decision('c0408', 'boundary_case', 'Sargus 4’s vote-driven punishment is not an established post-work provisioning mechanism.', ['src-sargus-vote-reference'], analysis='Reputation-based governance and material automation are separate claims; Union institutions cannot be borrowed.', follow_up='Keep as a coercive reputation-system comparison.'),
    decision('c0409', 'boundary_case', 'The Macra colony’s humans perform actual gas extraction.', ['src-macra-terror-reference'], analysis='Brainwashing and imposed leisure rituals do not make useful mining dispensable or its biological rulers AI.', follow_up='Keep as a forced-resource-labor comparison.'),
    decision('c0410', 'boundary_case', 'Pluto’s Company exploits actual industrial workers rather than a verified technologically dispensable workforce.', ['src-sun-makers-official'], analysis='Energy abundance, monopoly and oppressive taxation are insufficient for either general post-work access or a zero variant.', follow_up='Keep as an energy-monopoly labor comparison.'),
    decision('c0411', 'boundary_case', 'Paradise Towers’ failing and murderous building automation does not establish durable resident support.', ['src-paradise-towers-reference'], analysis='Maintenance machinery, sales promises and predation do not supply the missing material-access order.', follow_up='Skip deeper serial reconstruction.'),
    decision('c0412', 'needs_evidence', 'Terra Alpha’s forced happiness and policing do not establish automated material provision.', ['src-happiness-patrol-official'], analysis='A robotic executioner and behavioral regime do not specify how ordinary necessities are produced and allocated.', follow_up='Skip deeper serial reconstruction.')
